-- Seed the intake flow so /get-started has a published definition before the
-- admin editor exists. The JSON is DEFAULT_INTAKE_FLOW from @joice/core
-- (packages/core/src/onboarding/default-flow.ts), canonicalised; a test in core
-- asserts the two stay equal. Idempotent: an existing flow (already edited or
-- published by an admin) is left alone, and the pointer is only set when empty.
INSERT INTO "onboarding_flows" ("key", "name")
VALUES ('intake', 'Intake')
ON CONFLICT ("key") DO NOTHING;
--> statement-breakpoint
